L001889	\section{Fidelity Bounds for \ds3 Ground State}
L001890	\label{app:fidelity_s3}
L001891	This section establishes lower and upper bounds on the fidelity of the
L001892	prepared state, $\rho$, with respect to the target ground state $|\text{gs}\rangle$.
L001893	The ground state is defined as the +1 eigenstate of the local vertex projectors ($A_v^{\mathbb{Z}_2}, A_v^{\mathbb{Z}_3}$) and local plaquette projectors ($B_p^{\mathbb{Z}_2}, B_p^{\mathbb{Z}_3}$).
L001894	Furthermore, within the ground state manifold, $|\text{gs}\rangle$ is uniquely identified by the +1 eigenspace of the horizontal and vertical non-contractable $S_3$ flux projectors, $Z_{\textrm{hori}}$ and $Z_{\textrm{vert}}$ (see Section~\ref{app:z2z3-decomposition}). We can express the projector onto the ground state as:
L001895	\begin{equation}
L001896	    \label{eq:state_projector}
L001897	    \ket{\text{gs}}\!\bra{\text{gs}} =
L001898	    \underbrace{
L001899	        \prod_{v} {A_v^{\mathbb{Z}_2}}
L001900	    }_{:= P_A^{\mathbb{Z}_2}} .\
L001901	    \underbrace{
L001902	        \prod_{v} {A_v^{\mathbb{Z}_3}}
L001903	    }_{:= P_A^{\mathbb{Z}_3}} .\
L001904	    \underbrace{
L001905	        \prod_{p} {B_p^{\mathbb{Z}_2}} .\
L001906	        \prod_{p} {B_p^{\mathbb{Z}_3}} .\
L001907	        Z_{\textrm{hori}} .\  Z_{\textrm{vert}}
L001908	    }_{:= P_B}
L001909	\end{equation}
L001910	While all projectors commute, allowing for simultaneous measurement, we group them into `product' projectors $P_A^{\mathbb{Z}_2}$, $P_A^{\mathbb{Z}_3}$, and $P_B$. These groupings are chosen to be as large as possible, subject to the constraint that their destructive measurement at the end of the circuit incurs minimal gate overhead.
L001911	
L001912	For the experimentally prepared density matrix $\rho$, the fidelity with respect to the target state $\ket{\text{gs}}$ is:
L001913	\begin{align}\label{eq:fidelity_exact}
L001914	    \bra{\text{gs}}\rho\ket{\text{gs}} &= \text{Tr}\left(\rho  \ket{\text{gs}}\!\bra{\text{gs}}  \right) \nonumber \\
L001915	    &= \text{Tr}\left(\rho \ P_A^{\mathbb{Z}_2} \ P_A^{\mathbb{Z}_3} \ P_B \right)
L001916	\end{align}
L001917	We define the expectation values of the product projectors as:
L001918	\begin{align}\label{eq:projector_exp_vals}
L001919	    \begin{split}
L001920	        p_A^{\mathbb{Z}_2} &:= \text{Tr}(\rho \ P_A^{\mathbb{Z}_2} ) \\
L001921	        p_A^{\mathbb{Z}_3} &:= \text{Tr}(\rho \ P_A^{\mathbb{Z}_2} ) \\
L001922	        p_B &:= \text{Tr}(\rho \ P_B )
L001923	    \end{split}
L001924	\end{align}
L001925	To derive a lower bound for the fidelity, we use the following inequality which holds for a set of $n$ commuting projectors $\{P_i\}$:
L001926	\begin{equation}
L001927	    \prod_{i=1}^n P_i \geq \left(\sum_{i=1}^n P_i\right) - (n-1)\mathbb{I}.
L001928	    \label{eq:projector_inequality}
L001929	\end{equation}
L001930	Taking the trace of both sides with the density matrix $\rho$, and applying Eqs.~\eqref{eq:fidelity_exact} and \eqref{eq:projector_exp_vals}, we obtain:
L001931	\begin{align}\label{eq:lower_bound}
L001932	    \text{Tr}\left(\rho \ P_A^{\mathbb{Z}_2} \ P_A^{\mathbb{Z}_3} \ P_B \right)
L001933	    &\geq \ (p_A^{\mathbb{Z}_2} + p_A^{\mathbb{Z}_B} + p_B - 2 )
L001934	\end{align}
L001935	Substituting the experimentally measured expectation values for the $3\times 3$  lattice gives:
L001936	\begin{align}
L001937	    \bra{\text{gs}}\rho\ket{\text{gs}} &\geq  0.93(3) + 0.84(3) + 0.81(4) - 2 \\
L001938	    &= 0.58(6),
L001939	\end{align}
L001940	and the per-qudit fidelity is
L001941	\begin{align}
L001942	    f:=\bra{\text{gs}}\rho\ket{\text{gs}}^{1/18} &\geq  0.970(5).
L001943	\end{align}
L001944	
L001945	
L001946	Similarly, to get the upper bound for fidelity, we use the fact that the product of projectors is bounded by any individual projector:
L001947	\begin{equation}
L001948	    \prod_{j=1}^n P_j \leq P_i \quad \forall i.
L001949	\end{equation}
L001950	Taking the trace with $\rho$ yields:
L001951	\begin{align}\label{eq:upper_bound}
L001952	    \text{Tr}\left(\rho \ P_A^{\mathbb{Z}_2} \ P_A^{\mathbb{Z}_3} \ P_B \right) &\leq \text{min} \left\{ p_A^{\mathbb{Z}_2},\ p_A^{\mathbb{Z}_B},\ p_B \right\}.
L001953	\end{align}
L001954	Substituting the expectation values, we obtain:
L001955	\begin{equation}
L001956	    \bra{\text{gs}}\rho\ket{\text{gs}} \leq 0.81(4).
L001957	\end{equation}
L001958	In summary, the fidelity per qudit, $f$, for the ground state of the \ds3 model on the $3\times3$ lattice is bounded by:
L001959	\begin{equation}
L001960	    0.970(5) \leq f \leq 0.988(3).
L001961	\end{equation}
